USE `food_delivery`;
SET FOREIGN_KEY_CHECKS=0;



-- ------------------------------------------------------------
-- Обезличивание тестовых данных
-- ------------------------------------------------------------
UPDATE `client`
SET `phone_number` = CONCAT('+375000000', LPAD(`id_client`, 3, '0')),
    `first_name` = 'Клиент',
    `last_name` = CONCAT('Тестовый ', `id_client`);

UPDATE `courier`
SET `phone_number` = CONCAT('+375111111', LPAD(`id_courier`, 3, '0')),
    `first_name` = 'Курьер',
    `last_name` = CONCAT('Тестовый ', `id_courier`);

UPDATE `address`
SET `street` = 'ул. Тестовая',
    `building` = '1',
    `floor` = '1',
    `apartment` = LPAD(`id_address`, 3, '0'),
    `entrance` = '1';

UPDATE `payment_method`
SET `name` = 'Тестовая карта',
    `last4` = '0000';
SET FOREIGN_KEY_CHECKS=1;
