INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (3,2,'Тыквенный суп',180,5.00,8.00,20.00,300,9.00,'Тыква, сливки, семечки','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.4256201510340242.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (4,3,'Веган ролл',250,8.00,10.00,35.00,200,11.00,'Лаваш, хумус, овощи','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.06152304995967128.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (5,4,'Ягодный боул',320,10.00,5.00,45.00,300,14.00,'Банан, клубника, ягоды','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.02797476313835434.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (6,3,'Индейка гриль',380,45.00,10.00,5.00,300,16.50,'Филе индейки, овощи гриль','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.8141793543212599.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (7,4,'Авокадо-тост ',410,12.00,28.00,22.00,240,15.50,'Хрустящий цельнозерновой тост с пастой из спелого авокадо, семенами тыквы, микрозеленью и идеально приготовленным яйцом пашот.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.9012246320610433.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (9,4,'Шакшука по-восточному',320,14.00,19.00,15.00,300,13.00,'Традиционная яичница, томленая в густом соусе из спелых томатов, болгарского перца, лука и восточных специй. Подается с двумя ломтиками поджаренного багета.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.16419825351210093.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (10,1,'Салат с киноа и креветками',280,18.50,9.20,24.00,280,14.50,'Легкий и питательный салат на основе суперфуда киноа с сочными тигровыми креветками-гриль, спелым авокадо, хрустящим огурцом и заправкой из оливкового масла холодного отжима и лимонного сока.','https://images.unsplash.com/photo-1505576399279-565b52d4ac71?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (11,1,'Греческий салат с фетой',210,6.00,14.50,8.20,300,11.00,'Классический средиземноморский салат из спелых томатов черри, хрустящего болгарского перца, огурцов, крымского лука и маслин Каламата. Подается с кубиками настоящей греческой феты и ароматным орегано.','https://images.unsplash.com/photo-1540420773420-3366772f4999?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (12,1,'Теплый салат с баклажанами',195,4.50,11.00,12.00,260,12.50,'Обжаренные на гриле хрустящие баклажаны, томаты черри и нежный сыр страчателла на подушке из свежей зелени рукколы, заправленные соусом сладкий чили и посыпаные кедровыми орешками.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.5498481501895611.webp');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (13,2,'Крем-суп из брокколи',155,6.20,8.50,13.50,300,8.50,'Нежный бархатистый суп-пюре из молодой брокколи и шпината на легких кокосовых сливках. Подается с хрустящими пшеничными гренками и очищенными семенами подсолнечника.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.3709727687242289.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (14,2,'Чечевичный суп с лимоном',220,11.50,4.20,28.00,320,8.00,'Густой, согревающий суп из красной чечевицы, томленой с восточными специями, зирой, морковью и луком. Подается с долькой свежего лимона, сок которого идеально раскрывает вкус.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.667779019729185.webp');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (16,3,'Стейк из тунца с кускусом',390,32.00,12.00,22.00,320,19.50,'Сочный стейк из филе дикого тунца слабой прожарки (medium rare) в кунжутной панировке. Подается с рассыпчатым кускусом, вялеными томатами и соусом песто.','https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (17,3,'Цыпленок су-вид со шпинатом',310,28.50,9.00,6.00,280,14.00,'Нежнейшее куриное филе, приготовленное по технологии су-вид при низкой температуре, благодаря чему сохраняется максимальная сочность. Подается со шпинатом в легком сливочном соусе.','https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (18,3,'Паста из цукини с креветками',215,14.00,8.50,11.00,250,16.00,'Низкоуглеводная альтернатива пасте: спагетти из свежего цукини (кабачка), быстро обжаренные с тигровыми креветками, томатами черри, чесноком и тертым сыром пармезан.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.3594989277016887.webp');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (19,4,'Сырники из фермерского творога',290,18.00,6.50,16.00,210,10.50,'Воздушные сырники из маложирного натурального творога без добавления белой муки и сахара. Подаются с соусом из протертой лесной черники и нежным йогуртом.','https://images.unsplash.com/photo-1533134242443-d4fd215305ad?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (20,4,'Зеленый омлет со шпинатом',260,14.50,16.00,4.00,200,9.50,'Пышный омлет из трех яиц с добавлением пюре из свежего шпината, сыра рикотта и семян чиа. Подается со слайсами спелого авокадо и листьями свежего салата.','https://images.unsplash.com/photo-1525351484163-7529414344d8?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (21,4,'Овсяные блинчики с бананом',275,8.20,5.00,32.00,220,8.00,'Аппетитные блинчики на основе овсяной муки и бананового пюре. Подаются с тонкими слайсами свежего банана, ягодами голубики и струйкой натурального кленового сиропа.','https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (22,1,'Салат Капрезе с песто',185,8.00,15.00,4.50,220,10.50,'Классическая итальянская закуска из сочных спелых томатов, нежного молодого сыра моцарелла и свежего базилика. Подается с соусом песто на основе кедровых орешков и капелькой густого бальзамического крема.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.5148023773801561.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (23,1,'Салат с уткой и грушей',310,14.00,18.00,16.00,250,15.50,'Изысканное сочетание подкопченного филе утиной грудки, карамелизированной в меду груши, мягкого сыра дорблю и свежих листьев шпината. Салат заправляется ягодным соусом и посыпается лепестками миндаля.','https://images.unsplash.com/photo-1540420773420-3366772f4999?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (24,1,'Салат Нисуаз с тунцом',325,24.50,14.00,18.00,310,16.00,'Сытный французский салат со слегка обжаренным филе тунца, перепелиными яйцами, отварным бейби-картофелем, стручковой фасолью, маслинами и томатами черри на подушке из микса салатов под горчичной заправкой.','https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (25,2,'Грибной крем-суп',165,5.00,11.50,10.20,300,8.50,'Ароматный бархатистый крем-суп из свежих шампиньонов и белых лесных грибов, томленых с луком и картофелем на нежирных сливках. Подается с микрозеленью и капелькой трюфельного масла.','https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (26,2,'Уха из лосося и судака',145,16.00,4.50,8.00,350,11.50,'Традиционный прозрачный рыбный суп из филе благородного лосося и нежного судака с беби-картофелем, сладкой морковью и репчатым луком. Перед подачей посыпается свежим укропом и зеленым луком.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.3840662161484255.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (27,2,'Томатный Гаспачо',110,2.50,5.00,12.00,280,7.50,'Освежающий холодный андалузский суп из протертых спелых томатов, грунтовых огурцов, сладкого перца и чеснока с добавлением бальзамического уксуса и оливкового масла. Отлично подходит для жаркого дня.','https://images.unsplash.com/photo-1547592180-85f173990554?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (28,3,'Тефтели из индейки с бататом',340,24.00,11.00,26.00,300,13.50,'Нежные фрикадельки из диетического фарша индейки, приготовленные на пару, под легким томатным соусом с базиликом. Подаются с воздушным и сладковатым пюре из запеченного батата.','https://images.unsplash.com/photo-1529042410759-befb1204b468?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (29,3,'Пряное карри с нутом',295,12.50,8.00,38.00,320,12.00,'Ароматное веганское индийское блюдо: нут (турецкий горох), тушенный с цветной капустой, кабачками, шпинатом и кокосовым молоком со смесью восточных специй карри, куркумы и имбиря.','https://images.unsplash.com/photo-1565557623262-b51c2513a641?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (30,3,'Стейк говяжий су-вид',420,36.00,22.00,4.00,260,22.00,'Стейк из постной мраморной говядины, приготовленный по технологии су-вид при низкой температуре, что делает мясо невероятно нежным. Слегка обжаривается на гриле и подается с перечным соусом.','https://images.unsplash.com/photo-1544025162-d76694265947?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (31,4,'Чиа-пудинг с кокосом и манго',190,4.50,8.20,22.00,180,9.00,'Полезный веганский суперфуд-десерт: семена чиа, набухшие в натуральном кокосовом молоке с добавлением ванили. Сверху выкладывается густое пюре из спелого сладкого тайского манго.','https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (32,4,'Яйца Бенедикт с лососем',380,21.00,19.50,14.00,210,14.50,'Классический утренний шедевр: два яйца-пашот с жидким желтком, ломтики слабосоленого лосося и свежий шпинат на цельнозерновом поджаренном тосте под легким домашним соусом Голландез.','https://images.unsplash.com/photo-1608039829572-78524f79c4c7?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (33,4,'Английский ПП-завтрак',410,26.00,18.00,14.00,310,13.00,'Сытный и сбалансированный завтрак: яичница-глазунья из двух яиц, поджаренные ломтики ветчины из индейки, тушеная в томатном соусе белая фасоль, шампиньоны на гриле и запеченный помидор.','https://images.unsplash.com/photo-1525351484163-7529414344d8?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (34,4,'Пшенная каша на кокосовом молоке',245,6.00,5.50,42.00,250,8.50,'Нежная и ароматная пшенная каша, сваренная на легком кокосовом молоке с добавлением запеченной сладкой тыквы. Перед подачей украшается лепестками миндаля и ягодами свежей голубики. Идеальный веганский завтрак.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.5317777729361187.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (35,4,'Зеленая гречка с авокадо',290,9.50,11.00,36.00,260,11.50,'Сытный и невероятно полезный соленый завтрак-каша: живая зеленая гречка, томленая со шпинатом, подается с половинкой спелого авокадо, семенами конопли и идеально сваренным яйцом-пашот.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.5605619437153107.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (36,4,'Запеченное яблоко с творогом',185,12.00,4.50,24.00,220,7.50,'Полезный фруктовый десерт-завтрак: крупное яблоко, запеченное с начинкой из фермерского обезжиренного творога, изюма, измельченных грецких орехов и щепотки ароматной корицы. Сладкий вкус без капли сахара.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.9243585898714592.webp');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (37,4,'Асаи боул с тропическими фруктами',210,4.00,5.20,34.00,240,14.00,'Густой холодный смузи из ягод асаи и банана. Сверху выкладывается аппетитная мозаика из свежих фруктов: сочного манго, киви, кокосовых слайсов, ягод клубники и безглютеновой гранолы.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.08634305171366718.webp');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (38,1,'Фруктовый салат в ананасе',170,2.50,1.20,38.00,300,12.00,'Красивый и освежающий тропический салат, подаваемый в половинке свежего ананаса. Внутри — сочные кусочки ананаса, спелой дыни, грейпфрута, винограда и мяты под легким соусом из лаймового сока.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.0447472283505036.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (39,1,'Салат с печеной грушей и фетой',230,7.50,14.00,18.00,240,13.00,'Сочетание теплых карамелизированных долек груши, солоноватого сыра фета и свежих листьев рукколы, заправленное медово-горчичным соусом и посыпанное тыквенными семечками.','https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (40,2,'Овощной минестроне',115,4.00,3.20,17.50,320,8.00,'Легкий и сытный итальянский суп на овощном бульоне из молодой брокколи, зеленого горошка, сельдерея, томатов и кабачков с добавлением свежего базилика и итальянских трав.','https://images.unsplash.com/photo-1547592180-85f173990554?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (41,2,'Томатный суп с морепродуктами',190,18.00,6.00,14.00,350,14.50,'Густой суп на основе протертых томатов в собственном соку с добавлением мидий, кальмаров и тигровых креветок, приправленный чесноком, тимьяном и белым сухим вином.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.03685227724501694.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (42,3,'Овощное соте с брокколи и спаржей',140,5.50,6.00,14.50,260,9.50,'Яркое диетическое горячее блюдо: соцветия брокколи, стручковая фасоль, молодая спаржа, болгарский перец и томаты черри, быстро обжаренные на кунжутном масле в соусе вок.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.1377579025220409.JPG');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (43,3,'Стейк из цветной капусты под соусом',180,6.20,10.50,15.00,280,11.00,'Запеченный на гриле крупный стейк из цветной капусты, маринованный в копченой паприке и травах. Подается под нежным веганским ореховым соусом кешью-чиз.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.8978734385578908.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (44,5,'Зеленый детокс-смузи',110,2.50,1.00,22.00,300,7.50,'Освежающий витаминный заряд для очищения организма: свежевыжатый сок из зеленых яблок, сельдерея, спелого киви, листьев шпината и мяты. Взбивается с добавлением кубиков льда.','https://images.unsplash.com/photo-1610970881699-44a5587cabec?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (45,5,'Кокосовый Матча-Латте',135,3.20,6.00,16.00,250,8.50,'Популярный тонизирующий напиток на основе японского зеленого чая матча высшего сорта, взбитого в нежную пену с натуральным кокосовым молоком без добавления сахара.','https://images.unsplash.com/photo-1536256263959-770b48d82b0a?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (46,5,'Имбирно-лимонный чай',45,0.80,0.20,10.00,400,6.00,'Ароматный согревающий напиток из свежего корня имбиря, лимонного сока, веточки мяты и ложечки натурального цветочного меда. Идеально укрепляет иммунитет в прохладную погоду.','https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (47,5,'Флэт Уайт на миндальном',78,4.00,5.20,3.80,200,7.00,'Бодрящий двойной эспрессо из 100% арабики средней обжарки с добавлением нежного взбитого миндального молока. Насыщенный кофейный вкус без лактозы.','https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (48,3,'Домашний ягодный морс',95,0.80,0.20,21.00,300,6.50,'Традиционный прохладительный напиток из лесных ягод — клюквы, черники и брусники. Варится при щадящей температуре, сохраняя все полезные витамины. Сладковатый вкус за счет капли сиропа топинамбура.','https://ndfruhzyxqtuilekaorp.supabase.co/storage/v1/object/public/dish-images/0.45150119939966094.jpg');
INSERT INTO `dish` (`id_dish`, `id_category`, `name`, `calories`, `proteins`, `fats`, `carbs`, `weight`, `price`, `description`, `image_url`) VALUES (49,4,'Детокс-сок Грейпфрут-Сельдерей',85,1.80,0.40,18.00,250,8.00,'Свежевыжатый сок холодного отжима из спелого розового грейпфрута, стебля сельдерея и зеленого яблока. Способствует ускорению обмена веществ и глубокому очищению организма.','https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=600');
